def lit(v):
 if v is None:return 'null'
 return "'"+str(v).replace("'","''")+"'"
lines=['-- 12 categorias, 12 temas, 6 modelos, 10 medalhas e 60 questões completas.','begin;']
for i,s in enumerate(categories):
 slug,title=s.split('|');lines.append(f"insert into public.categories(slug,title,icon_key,sort_order) values({lit(slug)},{lit(title)},{lit(slug)},{i}) on conflict(slug) do nothing;")
colors=['#FF5A00','#FFB95A','#0E7C86','#3B3FA8','#FFB000','#8A2200']
for i,s in enumerate(categories):
 slug,title=s.split('|');lines.append(f"insert into public.themes(slug,title,primary_color,pattern_key,mascot_key) values({lit(slug)},{lit(title)},{lit(colors[i%6])},{lit('pattern-'+slug)},{lit('fenara-avatar')}) on conflict(slug) do nothing;")
for slug,title in templates:
 lines.append(f"insert into public.templates(slug,title,description,content) values({lit(slug)},{lit(title)},{lit('Modelo inicial para '+title.lower())},{lit(json.dumps({'question_kind':'multiple_choice','time_limit_seconds':20}))}::jsonb) on conflict(slug) do nothing;")
for slug,title in [('primeiro-quiz','Primeiro Quiz'),('sequencia-7-dias','Sequência de 7 dias'),('cem-por-cento','100% de acerto'),('criador','Criador'),('velocista','Velocista'),('mestre-combo','Mestre do Combo'),('explorador','Explorador'),('campeao','Campeão'),('estudioso','Estudioso'),('maratonista','Maratonista')]:
 lines.append(f"insert into public.badges(slug,title,description,icon_key,rule_key) values({lit(slug)},{lit(title)},{lit('Conquista: '+title+'.')},{lit(slug)},{lit(slug)}) on conflict(slug) do nothing;")
for title,category,questions in banks:
 assert len(questions)==10
 slug={'Viagem pelo Conhecimento':'viagem-conhecimento','Ciência em Ação':'ciencia-em-acao','História em 10 Perguntas':'historia-dez-perguntas','Desafio dos Mapas':'desafio-dos-mapas','Matemática Sem Medo':'matematica-sem-medo','Universo Digital':'universo-digital'}[title]
 # IDs determinísticos para idempotência sem auth users
 quizid='00000000-0000-4000-8000-'+f'{len(lines)%1000000000000:012d}'
 # Use UUID5 rather than changing line count
 import uuid
 quizid=str(uuid.uuid5(uuid.NAMESPACE_DNS,'fenara.quiz.'+slug))
 lines.append(f"insert into public.quizzes(id,slug,title,description,category_id,theme_id,difficulty,visibility,status,published_at) select {lit(quizid)}::uuid,{lit(slug)},{lit(title)},{lit('Dez perguntas para aprender e se divertir!')},c.id,t.id,2,'public','published',now() from public.categories c join public.themes t on t.slug=c.slug where c.slug={lit(category)} on conflict(id) do nothing;")
 for p,(prompt,right,*rest) in enumerate(questions):
  *wrong,explain=rest
  qid=str(uuid.uuid5(uuid.NAMESPACE_DNS,f'fenara.{slug}.{p}'))
  lines.append(f"insert into public.questions(id,quiz_id,kind,position,prompt,time_limit_seconds,base_points,explanation) values({lit(qid)}::uuid,{lit(quizid)}::uuid,'multiple_choice',{p},{lit(prompt)},20,1000,{lit(explain)}) on conflict(id) do nothing;")
  options=[wrong[0],right,wrong[1],wrong[2]] if p%2 else [right,*wrong]
  for oi,label in enumerate(options):
   oid=str(uuid.uuid5(uuid.NAMESPACE_DNS,f'fenara.{slug}.{p}.{oi}'))
   lines.append(f"insert into public.options(id,question_id,position,label) values({lit(oid)}::uuid,{lit(qid)}::uuid,{oi},{lit(label)}) on conflict(id) do nothing;")
  ci=options.index(right)
  correctid=str(uuid.uuid5(uuid.NAMESPACE_DNS,f'fenara.{slug}.{p}.{ci}'))
  lines.append(f"insert into public.answer_keys(question_id,correct_option_id) values({lit(qid)}::uuid,{lit(correctid)}::uuid) on conflict(question_id) do nothing;")
lines.append('commit;')
p=root/'supabase/seed.sql';p.write_text('\n'.join(lines)+'\n')
print('Generated',p,'quizzes',len(banks),'questions',sum(len(q) for _,_,q in banks),'lines',len(lines))
